//! Finite document assembly using only the generic rendering kernels.
use crate::{IndependentRoot, Initial};
use leptos::prelude::*;
use stackpress_leptos::render::{RenderError, RenderLimits};
use std::convert::Infallible;

/// Assemble this consumer's inert configuration, replay and external bootstrap.
/// Only checked enum/locale tokens are interpolated; component/replay bytes are
/// already generated by Leptos/the checked generic replay serializer.
pub fn document(initial: &Initial, csr: bool, body: String, replay: String) -> String {
    let theme = initial.theme.as_str();
    let locale = initial.language.locale();
    let mode = if csr { "csr" } else { "hydrate" };
    format!(
        "<!DOCTYPE html><html lang=\"{locale}\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><!--HEAD--></head><body><div id=\"independent-root\">{body}</div><script id=\"independent-config\" type=\"application/json\">{{\"theme\":\"{theme}\",\"language\":\"{locale}\",\"mode\":\"{mode}\"}}</script><script id=\"independent-replay\" type=\"application/json\">{replay}</script><script type=\"module\" src=\"/assets/start.js\"></script></body></html>"
    )
}

/// Render the real root or an empty CSR mount shell under the supplied byte ceiling.
/// # Errors
/// Retains generic executor, metadata, replay and complete-document limit failures.
pub async fn render(
    initial: Initial,
    csr: bool,
    limits: RenderLimits,
) -> Result<String, RenderError<Infallible>> {
    let component_initial = initial.clone();
    let component = move || {
        Ok::<_, Infallible>(if csr {
            ().into_any()
        } else {
            view! {<IndependentRoot initial=component_initial/>}.into_any()
        })
    };
    #[cfg(feature = "async")]
    {
        stackpress_leptos::async_render::AsyncRenderer::try_prepare(
            limits,
            component,
            || Ok(()),
            move |body, replay| Ok(document(&initial, csr, body, replay)),
        )?
        .await
    }
    #[cfg(not(feature = "async"))]
    {
        stackpress_leptos::render::Renderer::try_prepare(limits, component, move |body| {
            Ok(document(&initial, csr, body, "[]".into()))
        })?
        .finish()
        .await
    }
}
